1	import fs from 'node:fs';
2	import path from 'node:path';
3	import crypto from 'node:crypto';
4	import assert from 'node:assert/strict';
5	export const base=path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/,'$1'));
6	export const project=JSON.parse(fs.readFileSync(path.join(base,'project.json'))).project;
7	export const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
8	export const read=r=>fs.readFileSync(path.join(project,r),'utf8');
9	export const json=r=>JSON.parse(read(r));
10	export const state=()=>json('.writer/state.json');
11	export function save(r,v){const f=path.join(project,r);fs.mkdirSync(path.dirname(f),{recursive:true});fs.writeFileSync(f,typeof v==='string'?v:JSON.stringify(v,null,2)+'\n',{flag:'wx'});return f;}
12	export function outer(r,v){fs.writeFileSync(path.join(base,r),JSON.stringify(v,null,2)+'\n',{flag:'wx'});}
13	export const log=l=>JSON.parse(fs.readFileSync(path.join(base,'cli-logs',l,'stdout.txt'),'utf8'));
14	export {fs,path,assert};
