1	import fs from 'node:fs';import path from 'node:path';
2	import {base,project,read,json,save,sha,outer,assert} from './c-utils.mjs';
3	const x=json('.writer/drafts/ad-cr-review52-57-template.json');assert.equal(x.expected_revision,284);x.operation_id='ad-c-restored-window52-57-current-r284';
4	const texts={},coverage=[];
5	for(const [ref,h] of Object.entries(x.source_hashes)){
6	 const unit=Number(ref.match(/\/(\d{4})-/)[1]),t=read(ref);assert.equal(sha(Buffer.from(t)),h);texts[unit]=t;
7	 const n=Math.ceil(t.length/1800);let at=0;const pages=[];
8	 for(let i=1;i<=n;i++){const label=`ccr-window${unit}-p${i}`,r=JSON.parse(fs.readFileSync(path.join(base,'read-pages',label+'.json'),'utf8'));assert.equal(r.sha256,h);assert.equal(r.from,at);assert.equal(r.text,t.slice(r.from,r.to));at=r.to;pages.push({label,page:i,from:r.from,to:r.to,sha256:h});}assert.equal(at,t.length);
9	 coverage.push({unit,ref,sha256:h,bytes:Buffer.byteLength(t),chars:t.length,han:(t.replace(/^#.*$/gm,'').match(/\p{Script=Han}/gu)||[]).length,pages});
10	}
