13	x.chapter_functions=[
14	{unit:52,
15	goal:o(52,'沈半日休息中既处理第二幅帘，又真给睡眠和独读留时间；女另练自己的收尾，母决定自选新灯。','我吃完要躺一下。','我今天想出去坐一阵。'),
16	obstacle:o(52,'上工已累、父等太阳/成品、公共外绳明早有人用、厚边不可能照愿望当天干；旧照片也缺背面并混旧时词。','一睡又不知道几点。','你若今天洗帘，别都压外头那根。'),
17	choice:o(52,'先真睡、只洗一幅自内绳、接受一夜半窗且自己收，不用邻居在家换取包收；父坐着卸钩，沈携原册外出。女拆本日尾一次/旧排留，另小纸记。','她没有定洗帘的闹钟。','这幅由自己收挂，没干便等'),
18	consequence:o(52,'真睡与外坐均发生，厚边仍潮待明日，父轻任务并未伤愈；母图纸仍原处，新背照随来客去，未证明到岸或外流全追齐。','这幅厚边还潮，明天再看，今天真的睡过、也出去坐过。','她不在后头替人添一个到了。'),
19	relationship_change:o(52,'父承认自己把女午前回家算在心里，既等结果也给休息；父女同看一页允许不同解读。母女先说各自照明需求。','是我自己算的。','你先看你的。')},
20	{unit:53,
21	goal:o(53,'把第二幅由自己收挂落实，又守正常工作；女孩有限接同事识纸/传话，不接未知整摞。','不是中午来一趟专收','这两张今天可以看完，其余我不答应了。'),
22	obstacle:o(53,'早/午厚边未干，父怕闭眼后背看天责任；旧钩口偏。女把接电话算轻，自己交付迟，拒整摞也使人不悦。','你若叫我看天，我闭眼也不踏实。','他来催的时候我还差两行。'),
23	choice:o(53,'明确偶淋可再晾不让父抢收，午间回看、下工实收，带旧钩去买两只1元/坏备用分收；女承认迟交责任后只认两张。','她从零钱里找出一块，把两只都收下。','这次是自己先答了能接，没把两头算齐，不是对方来早。','两只一块。'),
24	consequence:o(53,'帘实际干/装回有色差、旧印不洗掉，备用新钩与坏钩各存；女孩交清原纸获实际回复，仍只换来短散步非整晚自由。','新钩一只装上，另一只放回碟中。','比留在窗上的那幅浅。','轻下来的一点时间，原来只够在这里来回走一小段'),
25	relationship_change:o(53,'父真实睡过/坐托干布而非被安排守候，画册由女主动递后父不等她翻页，双方等看；同事亲问后接回原件并听女准点走。','等会儿。这页还没看完。','我想准点走。')},
26	{unit:54,
27	goal:o(54,'母为自己的字和慢戏取得独立桌边照明，非借女借口消费；女孩保留自己的光与书。','她要在这里放自己的灯。'),
28	obstacle:o(54,'桌/杯/篮/线各占地方，48/82/68价与三款取舍，店光不等家光；亲人偏好不同且仍想获认同。','四十八的开关关了','偏偏还想再听亲近的人认一遍。'),
29	choice:o(54,'带自己信封/折纸真试，回家摆食具/休息后正常班，交班再买盒中新同款68、100找32、单票；电话问女后明确这一盏自己用。','这一盏我用。','数了三十二找给她。'),
30	consequence:o(54,'灯抱回/实际调影及反光，母字可读而两空仍未准；女试不惯暖光回屋，母真听完一回，旧灯未修。','这回她从开头听到了结尾，中间没有再拖回去。','还是不准。'),
31	relationship_change:o(54,'母承认早晨就为自己想买，不因女不喜欢就退；女不需证明共同爱好才承认各用。母听女工作迟交和拒接，不替她劝客气。','不是你电话说要回屋，我才去买。','明天再碰见，就碰见。')},
32	{unit:55,
33	goal:o(55,'周实到当前新牌柜户，从真人取物分清门/桌/放物限制，与两人定本次有限活；女为周三问自身硬尾组织具体问题。','先拿你常拿的，别为我挑最好拿的。'),
34	obstacle:o(55,'照片漏下蹭/旧孔松，男人想一回换且看出花钱，女人需半桌/原门/离家时间；报价问细时周怕逼人说快了。','也没说不做。我们问一问，你又像要收包。'),
35	choice:o(55,'获准定暂存后拆，实见两孔才补固，双方选原门原合页，工46库存料12共58装后验付；今天待稳不强复装。女留旧尾/另纸问结或层叠、不接母袋。','工四十六，料十二，合五十八。','这回拆开看，不另收一笔。'),
36	consequence:o(55,'两孔已补、原门墙边/零件干盒/日碗盖盒，58未收，周三9—10待验装；女纸布分收，母自己另袋不挤女课。','旁边添“未收”','原门靠柜旁、零件在干盒、待稳复装几行仍留原处'),
37	relationship_change:o(55,'两人不再替对方假定整换，周纠正被问即退的口气，女人自选保留；女孩见旧工作两页被取，无道歉仍能走，母承认女先练自身。','我说不好拿，你说换。我还以为你看中了哪种新的。','纸上摸不出硬。')},
38	{unit:56,
39	goal:o(56,'周把已补旧孔转成复装与本人真实验用，结本次款；女正常工作吃饭后带原问题到第六课前，周/沈/母另各有生活。','得摸到看清。昨晚你照那张，只见桌面。'),
40	obstacle:o(56,'门不蹭不等盘碗和坐写都顺，桌腿限膝/背后过路，盘挪位置可遮实际收益；沈糕摆对仍漏听，女害怕旧问题做得少。','我坐这里写东西，椅子得拉出来。','手背仍要从门边过。'),
41	choice:o(56,'先亲检稳/原件装回，常用者原位盘碗真试、坐椅写/男亲坐/小转桌角/先招呼，末后自改日用摆放并接受侧身；收60找2净58。女取原纸添先看不拆。','我要知道能不能拿，不是要天天拿。','从钱夹找出两元，交到他手里。'),
42	consequence:o(56,'本次工作由问照片到有限交付可结，原纸补实收/原件全复用，周真赴非维修喝茶；糕试半时不证增销、8册实还沈/父袋轻移。女已到未开课。','这次这样。我不用新的了。','说先放好，七点再开始。'),
43	relationship_change:o(56,'使用者能在验收时保留限制，男人从拖椅改先招呼；父女可不喜欢同种结尾，父还书非占有；女与同学先承认想被夸。','我也没说你不许等结尾。','我上回还嫌家里说不出哪里好，真要他先说这里歪，我也不愿意。')},
44	{unit:57,
45	goal:o(57,'第六课让老师真看两纸/旧尾，自己在新空边辨末角与结，并将有限结果带回自己的关系。','这张只记自己的练习。'),
46	obstacle:o(57,'看手势漏布层、左手夹进未结先翘；想多做/想夸又怕真话。老师还须顾他人、同学有自己衣物和饥饿、母要先听完一句。','自己这次还没收结','想要她看得准，又想要她先夸。'),
47	choice:o(57,'旧尾留给看/新处只退最后一下，松手再自收且承认仍厚，不另起针；短托同学即还手；回家等母并明说想听夸。','前面的短段还在，不用照上次一样退完后面两针。','那你能不能先说我做得还行？'),
48	consequence:o(57,'新角较散仍厚，48原段/52旧尾保留，自纸真添位置过程；老师已读48夜行/纸还女，20:40齐针回。母真摸不同，沈仅文字问回才懂，书签实际移停页。','这边散一点。','将书签夹到自己停的地方。'),
49	relationship_change:o(57,'女孩接受旁人有自己的目标和时间，又能直求亲近；母回应而不被拉整晚陪练，沈先误会再问回，信息不共享。','等这句完','自己又不是不肯夸她，偏等她从那堆布里猜')}
50	];
51	const sim=(units,judgment,differences,preserve,qs,optional_adjustments=[])=>({units,judgment,differences,preserve,optional_adjustments,uncertainty:'同一创作模型知情判断；完整实读当前版本，不能证明陌生读者的耐心或市场收益。',evidence:qs.flatMap(([u,q])=>ev(u,q))});
52	x.comparison={similar_structures:[
53	sim([52,53],'两章都由休息/自担劳动面对父亲与邻居，且多次摸厚边；并非两次相同完成。','52先睡再只洗一幅，夜厚边仍潮，选择得到外坐却承担跨日；53早午不干/来回少了午饭时间，真买钩装回后接受色差；53又用女孩迟交带出过度代接的实际损失。','保留没干这一夜与钩/色差后果，父既睡得成也能看书，不退回全天等女。',[[52,'这幅厚边还潮，明天再看'],[53,'午间跑这一趟，什么也没收回来，还少了半顿慢慢吃饭的工夫。']]),
54	sim([55,56],'都在柜前通过试用细化有限工作，盘/碗/桌反复可能令人觉得工序拖长。','55判断并交易选择、补固待稳/零收；56承载已修成果的本人验用，新增坐写与椅背过路、原位盘/大碗到自选摆放，实际款进入钱夹；做与用不能并作一次口头认可。','保留56坐椅与日用盘/偶用大碗用途差别、净58找2及全部旧件回位。',[[55,'旁边添“未收”'],[56,'我找你两块。'],[56,'我坐这里写东西，椅子得拉出来。']],['若另有压缩授权，可减少验用后的边界旁白；本轮保留实际试坐/选择/款的因果。']),
55	sim([52,55,57],'女孩多次展开同一练布/另记一纸/旧针留；有辨方向、收物、放手摸的重复阅读成本。','52自己试拆本日末尾一次仍硬；55准确定位并保留硬尾待师，不练新针；57师真看后新空边发生未结先翘/只退最后一下、自收，旧尾没被冒称修好。','保留同一实物上不同日期/不同角的证据与老师知情的新入口，不把正常准备写成已经学会。',[[52,'只写今天自己折边收尾，拆过一回，放手仍有硬点。'],[55,'纸上摸不出硬。'],[57,'前面的短段还在，不用照上次一样退完后面两针。']]),
56	sim([54,57],'亲近者想要认可，灯/布在桌上真用后仍不同；有回家展示再解说的结构相似。','54母先想听女认灯，最后说自己早就想买，各用光；57女从同学承认想夸走到直说，先等母听完一句，母实际摸且保留不同。这是角色位置交换与表达的变化。','保留母慢戏与女独读，别让亲近自动等于共享偏好。',[[54,'偏偏还想再听亲近的人认一遍。'],[57,'那你能不能先说我做得还行？']]),
57	sim([54,56,57],'吃饭/杯水/桌位和“不必/没有”边界叙述贯穿，整体安静，可能增加阅读停顿。','54饭桌试摆是购买的物理限制；56坐写是验收遗漏条件、杯茶是周真正非维修社交；57等一句戏是照顾母自己的时间，手酸是学习实际代价。不能只见水杯就判同场重写。','保留有目标和代价的动作；可选精简的是随后再解释边界的旁白，不是把合作场面改成强冲突。',[[54,'吃饭就先吃，想看字时收了碗'],[56,'那你来夸两句。我这里正好没什么好消息。'],[57,'回来几分钟都不能给自己留']],['可选检查57重复核针/纸分层及回家向沈再述的长度；不据此宣称有硬错或自动改正文。'])
58	],distinct_gains:[
