1	import {fs,path,base,project,read,json,sha,save,outer,assert,state} from './c-utils.mjs';
2	const x=json('.writer/drafts/ad-dr-review55-60-original.json');assert.equal(state().revision,290);x.operation_id='ad-d-restored-window55-60-r290';
3	const texts={},coverage=[];for(const[r,h]of Object.entries(x.source_hashes)){const unit=Number(r.match(//(\d{4})-/)[1]),t=read(r);assert.equal(sha(Buffer.from(t)),h);texts[unit]=t;const pages=[];let at=0;for(let i=1;i<=Math.ceil(t.length/1800);i++){const label=`ddr-window${unit}-p${i}`,v=JSON.parse(fs.readFileSync(path.join(base,'read-pages',label+'.json')));assert.equal(v.sha256,h);assert.equal(v.from,at);assert.equal(v.text,t.slice(v.from,v.to));at=v.to;pages.push({label,page:i,from:v.from,to:v.to,sha256:h});}assert.equal(at,t.length);coverage.push({unit,ref:r,sha256:h,chars:t.length,han:(t.replace(/^#.*$/gm,'').match(/\p{Script=Han}/gu)||[]).length,pages});}
4	const ev=(u,...qs)=>qs.map(quote=>{assert(texts[u].includes(quote),`${u}:${quote}`);return{unit:u,quote}}),o=(u,text,...qs)=>({status:'observed',text,evidence:ev(u,...qs)});
5	x.chapter_functions=[
6	{unit:55,goal:o(55,'周到柜户从真人取用确定一处可做的活；女为自己的硬尾形成问题。','先拿你常拿的，别为我挑最好拿的。'),obstacle:o(55,'照片漏下蹭/孔松，男人要看出花钱而女人要半桌/原门；报价问细时周过早退让。','我们问一问，你又像要收包。'),choice:o(55,'双方同意本次原门补孔待稳复装，工46库存料12共58，先不收款。女保留硬尾待师，不接母袋当夜修。','工四十六，料十二，合五十八。','那做这一处。'),consequence:o(55,'门墙边/原零件盒上干处、待周三9—10再验装，未收58；用者承担晚饭盖盒不顺。','旁边添“未收”','晚使用者告浅盘在盖盒'),relationship_change:o(55,'夫妻发现各替对方猜整换，周承认问钱即收包说急了；母容女自己的练习优先。','我说不好拿，你说换。我还以为你看中了哪种新的。','纸上摸不出硬。')},
7	{unit:56,goal:o(56,'完成复装后把决定交给常用者的实际验用、收款；女吃过后真正赴第六课门前。','得摸到看清。昨晚你照那张，只见桌面。'),obstacle:o(56,'修好门不消桌腿/椅背/手背余限，挪盘能掩盖修理收益；沈改摆仍漏听，女惧做少。','我坐这里写东西，椅子得拉出来。','手背仍要从门边过。'),choice:o(56,'原位浅盘/大碗真试、坐写/男亲坐/略转桌角并先招呼，用者自改摆放且接受侧身；60找2净58。','我要知道能不能拿，不是要天天拿。','从钱夹找出两元，交到他手里。'),consequence:o(56,'本次有限交付/原件全复用/原未收旁补实收，周真赴茶友；父8册借看后真还、袋轻用，女已坐未开课。','这次这样。我不用新的了。','说先放好，七点再开始。'),relationship_change:o(56,'用者保留限制仍可认可工作，父女不同结尾不剥夺彼此；女孩与同学先承认想夸。','我也没说你不许等结尾。','真要他先说这里歪，我也不愿意。')},
